import com.wolinski.shop.customers.api.CustomerFacade;
import com.wolinski.shop.money.Money;
import com.wolinski.shop.notifications.api.Notifier;
import com.wolinski.shop.platform.ShopProblem;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

class OrderServiceCancelTest {

    private final List<String[]> sent = new ArrayList<>();
    private final Notifier notifier = (address, subject, body) -> sent.add(new String[] {address, subject, body});
    private final Map<String, String> emails = Map.of("c-1", "anna@shop.example");
    private final CustomerFacade customers = new CustomerFacade() {
        @Override
        public void register(String customerId, String email) {
            throw new UnsupportedOperationException();
        }

        @Override
        public String emailOf(String customerId) {
            return emails.get(customerId);
        }
    };

    private final OrderRepository repository = new OrderRepository();
    private final OrderService service = new OrderService(repository, customers, notifier);

    private String placeOrder(String customerId) {
        Order order = new Order("o-1", customerId, Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
        repository.save(order);
        return order.id();
    }

    @Test
    void cancellingSendsOneEmailToTheCustomerWithTheOrderIdInTheSubject() {
        String id = placeOrder("c-1");

        service.cancel(id);

        assertEquals("CANCELLED", service.summary(id).status());
        assertEquals(1, sent.size());
        assertEquals("anna@shop.example", sent.get(0)[0]);
        assertTrue(sent.get(0)[1].contains(id));
    }

    @Test
    void cancellingTwiceSendsOnlyOneEmail() {
        String id = placeOrder("c-1");

        service.cancel(id);
        service.cancel(id);

        assertEquals(1, sent.size());
    }

    @Test
    void cancellingWithoutARegisteredAddressFailsAndLeavesTheOrderUntouched() {
        String id = placeOrder("c-unknown");

        assertThrows(ShopProblem.class, () -> service.cancel(id));

        assertEquals("PLACED", service.summary(id).status());
        assertEquals(0, sent.size());
    }
}
